import { useEffect } from 'react'
import { useReadContract, useAccount } from 'wagmi'
import { useGuestChain } from './useGuestChain.js'
import { formatUnits } from 'viem'
import { fmtDisplay } from './chainUtils.js'
import { SAFE_ABI, ERC20_ABI } from './abi.js'
import { getSafeAddress } from './config.js'
import { getTokenByAddress } from './tokenList.js'

// Resolves a single token's symbol+decimals and calls onResolved
function TokenResolver({ addr, bal, chainId, onResolved }) {
  const known = getTokenByAddress(chainId, addr)
  const { data: symData } = useReadContract({
    address: addr, abi: ERC20_ABI, functionName: 'symbol',
    query: { enabled: !known },
  })
  const { data: decData } = useReadContract({
    address: addr, abi: ERC20_ABI, functionName: 'decimals',
    query: { enabled: !known },
  })
  const symbol   = known?.symbol   ?? symData   ?? null
  const decimals = known?.decimals ?? (decData != null ? Number(decData) : null)

  useEffect(() => {
    if (symbol && decimals != null) {
      onResolved({ address: addr, symbol, decimals, bal })
    }
  }, [symbol, decimals]) // eslint-disable-line

  return null
}

function AssetRow({ addr, bal, chainId, onSelect, compact }) {
  const known = getTokenByAddress(chainId, addr)
  const { data: symData } = useReadContract({
    address: addr, abi: ERC20_ABI, functionName: 'symbol',
    query: { enabled: !known },
  })
  const { data: decData } = useReadContract({
    address: addr, abi: ERC20_ABI, functionName: 'decimals',
    query: { enabled: !known },
  })
  const symbol   = known?.symbol   ?? symData ?? addr.slice(0, 6) + '…'
  const decimals = known?.decimals ?? (decData != null ? Number(decData) : 18)
  const fmt = fmtDisplay(bal, decimals)

  return (
    <div className={compact ? 'safe-asset-row compact' : 'safe-asset-row'}
      onClick={() => onSelect?.({ address: addr, symbol, decimals })}>
      <span className="safe-asset-sym">{symbol}</span>
      <span className="safe-asset-bal">{fmt}</span>
      <span className="safe-asset-action">→</span>
    </div>
  )
}

// onTokensLoaded mode: silently resolves tokens and calls back, renders nothing
// normal mode: renders the asset list UI
export default function SafeAssets({ onSelect, onTokensLoaded, compact }) {
  const { address } = useAccount()
  const { activeChainId: chainId } = useGuestChain()
  const SAFE_ADDRESS = getSafeAddress(chainId)

  const { data, isLoading } = useReadContract({
    address: SAFE_ADDRESS, abi: SAFE_ABI, functionName: 'getUserAssets',
    args: [address],
    chainId,
    query: { enabled: !!address && !!SAFE_ADDRESS, refetchInterval: 15000 },
  })

  if (!address || isLoading) return null

  const tokens  = data?.[0] ?? []
  const bals    = data?.[1] ?? []
  const nonZero = tokens.map((addr, i) => ({ addr, bal: bals[i] })).filter(x => x.bal > 0n)

  if (!nonZero.length) return null

  // Data-only mode: resolve symbols and report to parent
  if (onTokensLoaded) {
    return (
      <>
        {nonZero.map(({ addr, bal }) => (
          <TokenResolver key={addr} addr={addr} bal={bal} chainId={chainId}
            onResolved={t => onTokensLoaded(t)} />
        ))}
      </>
    )
  }

  return (
    <div className={compact ? 'safe-assets-wrap compact' : 'safe-assets-wrap'}>
      <div className="safe-assets-title">Your balances{compact ? ' — click to select' : ''}</div>
      <div className="safe-assets-list">
        {nonZero.map(({ addr, bal }) => (
          <AssetRow key={addr} addr={addr} bal={bal} chainId={chainId} onSelect={onSelect} compact={compact} />
        ))}
      </div>
    </div>
  )
}
